//! Ported rvl-cli data commands (po-av01j.17).
//!
//! rvl-cli (Go) is the contract source of truth: same subcommands, same
//! flags, byte-identical JSON output on the `--format=json` paths.
//! Human-readable output may improve. Each ported slice carries a
//! golden-parity suite; goldens under `testdata/` are generated by Go
//! itself against the exact rvl-cli structs (`testdata/generate_goldens.go`).
//!
//! Exit-code contract (mirrors rvl-cli's `cliutil`):
//!   0  success (including help)
//!   1  runtime failure (API error, auth failure, network problem)
//!   2  usage error (unknown flag, invalid argument) — clap parse errors
//!      already exit 2; validation failures use [`Failure::usage`].
//!
//! The binary is named `rvl` (renamed from `rvlscan` at the v1.0.0 cutover,
//! po-av01j.154); every user-facing hint routes through [`BIN`] (defined in
//! `rvl-core`, re-exported here), which is why the rename was one constant.

pub mod auth;
pub mod client;
pub mod config;
pub mod control;
pub mod display;
pub mod evidence;
pub mod feedback;
pub mod gojson;
pub mod incident;
pub mod knowledge;
pub mod project_config;
pub mod project_mapping;
pub mod risk;
pub mod scan_cached_output;
pub mod scan_normalize;
