pub mod scan_team;
pub mod stpa;

use std::process::ExitCode;

/// The binary name used in user-facing hints ("run 'rvl login'"), re-exported
/// from [`rvl_core`] so the ~57 `rvl_data::BIN` call sites keep working while
/// crates that do not depend on rvl-data can reach the same constant.
pub use rvl_core::BIN;

/// A command failure: the exact stderr message plus the process exit code.
#[derive(Debug, PartialEq, Eq)]
pub struct Failure {
    pub msg: String,
    pub code: u8,
}

impl Failure {
    /// Runtime failure (exit 1): API error, auth failure, network problem.
    pub fn runtime(msg: impl Into<String>) -> Self {
        Failure {
            msg: msg.into(),
            code: 1,
        }
    }
    /// Usage error (exit 2): invalid argument or flag value.
    pub fn usage(msg: impl Into<String>) -> Self {
        Failure {
            msg: msg.into(),
            code: 2,
        }
    }
}

/// stdout on success, (stderr, exit code) on failure.
pub type CmdResult = Result<String, Failure>;

/// Print a command result the way rvl-cli does: stdout verbatim on
/// success, the failure message to stderr + its exit code otherwise.
pub fn finish(res: CmdResult) -> ExitCode {
    match res {
        Ok(out) => {
            print!("{out}");
            ExitCode::SUCCESS
        }
        Err(f) => {
            eprintln!("{}", f.msg);
            ExitCode::from(f.code)
        }
    }
}
